package com.tencent.weknora.knowledge;

import static org.assertj.core.api.Assertions.*;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;
import com.sun.net.httpserver.HttpServer;
import com.tencent.weknora.model.*;import com.tencent.weknora.security.*;import com.tencent.weknora.task.*;
import java.net.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import java.util.stream.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.mock.env.MockEnvironment;

/** Actual Go service SQL/model oracle, including fixed ownership changes during generation. */
class KnowledgeBaseProfileGoParityTest {
 @TempDir Path temp;final ObjectMapper json=new ObjectMapper();
 static {try{com.tencent.weknora.retrieval.NativeDatabaseRuntime.initialize();}catch(java.sql.SQLException e){throw new ExceptionInInitializerError(e);}}
 @TestFactory Stream<DynamicTest> actualGoKnowledgeBaseDescriptions()throws Exception{JsonNode cases;try(var in=getClass().getResourceAsStream("/go-knowledge-base-profile.json")){cases=json.readTree(in);}assertThat(cases.size()).isEqualTo(52);var seq=new AtomicInteger();return StreamSupport.stream(cases.spliterator(),false).map(row->DynamicTest.dynamicTest(row.path("name").asText(),()->compare(row,seq.incrementAndGet())));}
 void compare(JsonNode oracle,int no)throws Exception{
  String name=oracle.path("name").asText().replace("http/","");boolean http=oracle.path("http").isObject();var f=new DocumentProcessingCompatibilityTest();f.temp=temp;f.database(no,false);var document=f.seed(json.createObjectNode().put("state","completed"));f.jdbc.update("DELETE FROM knowledges WHERE id='knowledge'");var base=oracle.path("knowledge_base");f.jdbc.update("UPDATE knowledge_bases SET name=?,type=?,is_temporary=?,summary_model_id=?,profile_config=?,generated_profile=? WHERE id='kb'",base.path("name").asText(),base.path("type").asText(),base.path("is_temporary").asBoolean(),base.path("summary_model_id").asText(),base.path("profile_config").isNull()?null:json.writeValueAsBytes(base.path("profile_config")),base.path("generated_profile").isNull()?null:json.writeValueAsBytes(base.path("generated_profile")));
  if(http)f.jdbc.update("UPDATE knowledge_bases SET creator_id=? WHERE id='kb'",name.equals("noncreator")?"another":"caller");
  int tag=0;for(var row:oracle.path("rows")){f.jdbc.update("INSERT INTO knowledges(id,tenant_id,knowledge_base_id,type,source,title,file_name,file_type,folder_path,created_at,parse_status,enable_status,profile) VALUES(?,1,'kb','file','manual',?,?,?,?,?,'completed','enabled',?)",row.path("id").asText(),row.path("title").asText(),row.path("file_name").asText(),row.path("file_type").asText(),row.path("folder_path").asText(),row.path("created_at").asText(),row.has("profile")?json.writeValueAsBytes(row.path("profile")):null);for(var t:row.path("tags")){String id="tag-"+(++tag);f.jdbc.update("INSERT INTO knowledge_tags(id,tenant_id,knowledge_base_id,name,seq_id) VALUES(?,1,'kb',?,?)",id,t.asText(),tag);f.jdbc.update("INSERT INTO knowledge_tag_relations(knowledge_id,tag_id) VALUES(?,?)",row.path("id").asText(),id);}}
  var text=new KnowledgeBaseProfileText(json,oracle.path("configured_prompt").asText(null));var repo=new KnowledgeBaseProfileRepository(f.jdbc,json,f.knowledge,f.manager,Clock.systemUTC());if(!oracle.path("aggregate").isNull())assertThat((JsonNode)text.aggregate(repo.rows(1,"kb"))).as("actual Go owner-scoped aggregate").isEqualTo(oracle.path("aggregate"));
  var payload=oracle.path("payload");var pending=f.tasks.enqueue(1,"kb:profile",null,payload,3,Duration.ZERO,"summary",Duration.ofMinutes(5));var job=f.tasks.claim("profile-worker",Duration.ofMinutes(10)).orElseThrow();assertThat(job.id()).isEqualTo(pending.id());
  if(name.equals("missing-kb"))f.jdbc.update("DELETE FROM knowledge_bases WHERE id='kb'");if(name.equals("foreign-kb"))f.jdbc.update("UPDATE knowledge_bases SET tenant_id=2 WHERE id='kb'");
  var requests=Collections.synchronizedList(new ArrayList<JsonNode>());var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/",exchange->{try{requests.add(json.createObjectNode().put("path",exchange.getRequestURI().getPath()).set("body",json.readTree(exchange.getRequestBody())));if(name.equals("owner-changed-during-chat"))f.jdbc.update("UPDATE knowledge_bases SET tenant_id=2 WHERE id='kb'");if(name.equals("delete-during-chat"))f.jdbc.update("DELETE FROM knowledge_bases WHERE id='kb'");if(name.equals("name-changed-during-chat"))f.jdbc.update("UPDATE knowledge_bases SET name='Renamed while model runs' WHERE id='kb'");int status=name.equals("chat-error")?503:200;ObjectNode response=status==503?json.createObjectNode().set("error",json.createObjectNode().put("message","synthetic provider failure")):json.createObjectNode().set("choices",json.createArrayNode().add(json.createObjectNode().put("finish_reason","stop").set("message",json.createObjectNode().put("role","assistant").put("content",oracle.path("reply").asText()))));byte[] bytes=json.writeValueAsBytes(response);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(status,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}}finally{exchange.close();}});server.start();
  var env=new MockEnvironment().withProperty("SSRF_WHITELIST","127.0.0.1").withProperty("SSRF_DNS_WHITELIST_ONLY","true");var models=new ModelClientFactory(f.jdbc,json,new GoSecretCodec(""),new ModelCatalogRuntime(f.jdbc,"","/nonexistent"),new ModelEgressPolicy(f.jdbc,json,env),env);
  try{for(String id:List.of("summary","override")){var parameters=json.createObjectNode().put("provider","generic").put("base_url","http://127.0.0.1:"+server.getAddress().getPort()+"/v1").put("api_key","synthetic-key");f.jdbc.update("INSERT INTO models(id,tenant_id,name,type,source,parameters,is_builtin,status) VALUES(?,1,'unknown','KnowledgeQA','remote',?,false,'active')",id,json.writeValueAsBytes(parameters));}var handler=new KnowledgeBaseProfileHandler(repo,json,(owner,id)->models.chat(new AuthContext("system-task",owner,"viewer",false,null,false,Set.of(),Set.of()),id),text,f.tasks,Clock.systemUTC());Exception failure=null;try{if(http)compareHttp(f,repo,models,text,oracle,name);else handler.execute(job,f.cancellation(job));}catch(Exception e){failure=e;}assertThat(failure!=null).as("actual Go retry/error decision: %s",failure).isEqualTo(!oracle.path("error").asText().isEmpty());assertThat(numbers(json.valueToTree(requests))).as("actual Go model provider HTTP including aggregate prompt/options").isEqualTo(numbers(oracle.path("requests")));
    var stored=f.jdbc.queryForList("SELECT tenant_id,name,generated_profile FROM knowledge_bases WHERE id='kb'");var actual=json.createObjectNode().put("TenantID",stored.isEmpty()?0:((Number)stored.getFirst().get("tenant_id")).longValue()).put("Name",stored.isEmpty()?"":stored.getFirst().get("name").toString());if(stored.isEmpty()||stored.getFirst().get("generated_profile")==null)actual.putNull("GeneratedProfile");else{var raw=stored.getFirst().get("generated_profile");actual.set("GeneratedProfile",raw instanceof byte[] b?json.readTree(b):json.readTree(raw.toString()));}assertThat(canonical(actual)).as("actual Go KB profile SQL; previous text retained on failure; owner fence").isEqualTo(canonical(oracle.path("stored")));
  }finally{models.close();server.stop(0);}
 }

 void compareHttp(DocumentProcessingCompatibilityTest f,KnowledgeBaseProfileRepository repo,ModelClientFactory models,KnowledgeBaseProfileText text,JsonNode oracle,String name)throws Exception{
  var expected=oracle.path("http");var scope=expected.path("scope");var caps=new HashSet<String>();scope.path("Capabilities").forEach(n->caps.add(n.asText()));var allowed=new HashSet<String>();scope.path("KnowledgeBaseIDs").forEach(n->allowed.add(n.asText()));
  var auth=new AuthContext("caller",expected.path("caller_tenant").asLong(),expected.path("role").asText(),false,expected.path("machine").asBoolean()?1L:null,scope.path("FullAccess").asBoolean(),caps,allowed);
  if(auth.tenantId()==2){
   f.jdbc.update("INSERT INTO organizations(id,name,owner_tenant_id,owner_id) VALUES('org','Org',1,'caller')");
   f.jdbc.update("INSERT INTO organization_tenant_members(id,organization_id,tenant_id,role) VALUES('source','org',1,'admin'),('member','org',2,?)",name.equals("shared-viewer")?"viewer":"editor");
   if(!name.equals("foreign-denied")){f.jdbc.update("INSERT INTO kb_shares(id,knowledge_base_id,organization_id,source_tenant_id,permission,shared_by_user_id) VALUES('share','kb','org',1,'editor','caller')");if(name.equals("shared-revoked"))f.jdbc.update("UPDATE kb_shares SET deleted_at=CURRENT_TIMESTAMP WHERE id='share'");}
  }
  var beans=new org.springframework.beans.factory.support.DefaultListableBeanFactory();beans.registerSingleton("jdbc",f.jdbc);beans.registerSingleton("json",json);beans.registerSingleton("tx",f.manager);beans.registerSingleton("authRepository",new AuthRepository(f.jdbc,json));beans.registerSingleton("codec",new KnowledgeBaseCodec(json));
  var audit=new org.springframework.beans.factory.support.RootBeanDefinition(Class.forName("com.tencent.weknora.security.DeniedRoleAuditService"));audit.setAutowireMode(org.springframework.beans.factory.support.AbstractBeanDefinition.AUTOWIRE_CONSTRUCTOR);beans.registerBeanDefinition("audit",audit);
  var writes=beans.createBean(KnowledgeBaseWriteAuthorization.class);
  var generator=new KnowledgeBaseProfileGenerator(repo,json,(owner,id)->models.chat(new AuthContext("system-task",owner,"viewer",false,null,false,Set.of(),Set.of()),id),text,Clock.systemUTC());
  var language=new KnowledgeProcessingLanguage(new MockEnvironment().withProperty("WEKNORA_LANGUAGE",expected.path("environment").asText()));
  var controller=new KnowledgeBaseProfileController(writes,generator,repo,language);
  var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(controller).setControllerAdvice(new com.tencent.weknora.api.ApiErrorAdvice()).build();
  var response=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/knowledge-bases/kb/profile/generate").requestAttr(CurrentAuth.ATTRIBUTE,auth).header("Accept-Language",expected.path("header").asText())).andReturn().getResponse();
  assertThat(response.getStatus()).as("production Go handler + role/capability/share middleware vs native MVC").isEqualTo(expected.path("status").asInt());
  assertThat(httpBody(json.readTree(response.getContentAsByteArray()))).as("complete actual Go profile HTTP body").isEqualTo(httpBody(expected.path("body")));
 }
 JsonNode httpBody(JsonNode raw){var value=raw.deepCopy();if(value.path("data").has("generated_at")){var data=(ObjectNode)value.get("data");assertThat(Instant.parse(data.path("generated_at").asText())).isNotNull();data.put("generated_at","__generated_time__");}return numbers(value);}
 JsonNode canonical(JsonNode raw){var n=raw.deepCopy();if(n.path("GeneratedProfile").isObject()){var p=(ObjectNode)n.get("GeneratedProfile");if(p.has("error")){assertThat(p.path("error").asText()).isNotBlank();p.put("error","__failure__");}if(p.has("generated_at")&&!p.path("generated_at").asText().equals("2020-01-01T00:00:00Z")){assertThat(Instant.parse(p.path("generated_at").asText())).isNotNull();p.put("generated_at","__generated_time__");}}return numbers(n);}
 JsonNode numbers(JsonNode n){if(n.isNumber())return DecimalNode.valueOf(n.decimalValue().stripTrailingZeros());if(n.isArray()){var a=json.createArrayNode();n.forEach(v->a.add(numbers(v)));return a;}if(n.isObject()){var a=json.createObjectNode();n.fields().forEachRemaining(e->a.set(e.getKey(),numbers(e.getValue())));return a;}return n;}
}
